-- Story 3.6 review fix (S3): `interactions_summary.can_moderate` mirrors the
-- UPDATE policy's FULL predicate now — `kind <> 'note' or
-- can_moderate_note(actor_member_id)` — not `can_moderate_note()` alone.
-- Generated by `supabase db diff`; hand-verified against the same class of
-- gap 20260729042335_add_interaction_soft_delete_and_note_authorship.sql
-- documents: `CREATE OR REPLACE VIEW` does not itself clear an
-- already-set `security_invoker` reloption (verified live on this exact
-- migration — `security_invoker=on` survived unchanged), so no `alter view
-- ... set (security_invoker = on)` is needed here the way it was needed the
-- first time this view was created. The defensive re-assertion below costs
-- nothing if it turns out to already hold, and removes any doubt for future
-- readers of this migration rather than relying on that verification note.
create or replace view "public"."interactions_summary" as  SELECT i.id,
    i.account_id,
    i.created_at,
    i.target_type,
    i.target_id,
    i.scope,
    i.reference_link_id,
    i.actor_member_id,
    i.kind,
    i.body,
    i.metadata,
    i.deleted_at,
    NULLIF(btrim(((COALESCE(m.first_name, ''::text) || ' '::text) || COALESCE(m.last_name, ''::text))), ''::text) AS author_name,
    ((i.kind <> 'note'::text) OR public.can_moderate_note(i.actor_member_id)) AS can_moderate
   FROM ((public.interactions i
     LEFT JOIN public.account_members am ON ((am.id = i.actor_member_id)))
     LEFT JOIN public.members m ON ((m.user_id = am.user_id)));

alter view "public"."interactions_summary" set (security_invoker = on);
